import{_ as t,o as n,c as r,j as a,a as e,a2 as i}from"./chunks/framework.BkKoiSIN.js";const _=JSON.parse('{"title":"检索、工具与多模态","description":"从模型输入、外部信息和执行反馈理解应用系统，并用任务证据检验收益。","frontmatter":{"title":"检索、工具与多模态","description":"从模型输入、外部信息和执行反馈理解应用系统，并用任务证据检验收益。","kind":"topic","status":"planned"},"headers":[],"relativePath":"applications/index.md","filePath":"applications/index.md"}'),o={name:"applications/index.md"};function d(s,l,u,p,c,h){return n(),r("div",null,[...l[0]||(l[0]=[a("h1",{id:"检索、工具与多模态",tabindex:"-1"},[e("检索、工具与多模态 "),a("a",{class:"header-anchor",href:"#检索、工具与多模态","aria-label":'Permalink to "检索、工具与多模态"'},"​")],-1),a("p",null,"这一组是待学习的横向主题，用来检验对模型、训练和服务系统的理解。通过有边界的小实验逐步深入，并复用共用的评测协议。接通API、搭建界面与掌握机制分别验收。",-1),a("h2",{id:"先区分增加了什么能力",tabindex:"-1"},[e("先区分增加了什么能力 "),a("a",{class:"header-anchor",href:"#先区分增加了什么能力","aria-label":'Permalink to "先区分增加了什么能力"'},"​")],-1),a("div",{class:"reading-table",role:"group","aria-label":"表格",tabindex:"0"},[a("table",null,[a("thead",null,[a("tr",null,[a("th",null,"方向"),a("th",null,"增加的环节"),a("th",null,"应掌握的问题"),a("th",null,"深入入口")])]),a("tbody",null,[a("tr",null,[a("td",null,"RAG"),a("td",null,"在生成前获取外部证据"),a("td",null,"是没有检索到，还是拿到证据仍答错？"),a("td",null,[a("a",{href:"/applications/retrieval-agents"},"检索与工具调用")])]),a("tr",null,[a("td",null,"工具调用与agent"),a("td",null,"让模型选择外部动作并读取反馈"),a("td",null,"参数是否正确、权限如何执行、何时停止？"),a("td",null,[a("a",{href:"/applications/retrieval-agents"},"检索与工具调用")])]),a("tr",null,[a("td",null,"视觉语言"),a("td",null,"把图像变为可被语言模型使用的表示"),a("td",null,"编码器、连接层、视觉token与监督怎样连接？"),a("td",null,[a("a",{href:"/applications/multimodal"},"多模态机制与成本")])]),a("tr",null,[a("td",null,"音频与视频"),a("td",null,"加入时间、采样与跨模态对齐"),a("td",null,"音频特征/帧数如何影响任务与成本？"),a("td",null,[a("a",{href:"/applications/multimodal"},"多模态机制与成本")])])])])],-1),i('<p>RAG论文将参数化生成器与外部检索记忆结合，也包含查询编码器与生成器的联合微调。本路线的首个小实验采用冻结模型的检索增强推理，分别观察检索与生成，不把它称为原论文训练流程的复现。<a href="https://arxiv.org/abs/2005.11401v4" target="_blank" rel="noreferrer">原论文v4</a>提供机制起点，现代工程流水线的配置仍需单独实验。</p><h2 id="学习依赖与实施顺序" tabindex="-1">学习依赖与实施顺序 <a class="header-anchor" href="#学习依赖与实施顺序" aria-label="Permalink to &quot;学习依赖与实施顺序&quot;">​</a></h2><ol><li>在<a href="/foundations/">模型基础</a>和<a href="/evaluation/">评测方法</a>中弄清输入token、输出与评分。</li><li>用小型公开语料建立检索与生成分离的基线，先看逐题证据和错误。</li><li>增加一个只读工具，记录参数、结果和终止状态；再比较固定工作流与模型选择动作的差异。</li><li>理解SFT的模板和监督后，阅读视觉编码器与连接层，先做输入处理与形状实验。</li><li>各分支完成自己的基础与小实验后再扩展：检索/工具走向多步任务，视觉/音频走向相应真实模型。不要求先做RAG或Agent才能学习VLM；训练和复杂多agent系统不作为入门门槛。</li></ol><p>ReAct给出交替使用推理与动作的研究路径；Anthropic的工程文章区分固定工作流和模型自主控制流程，并提醒复杂度会增加延迟与成本。这里采用这些概念安排对照，不把任何一种模式预设为更优。<a href="https://arxiv.org/abs/2210.03629v3" target="_blank" rel="noreferrer">ReAct v3</a>、<a href="https://www.anthropic.com/research/building-effective-agents" target="_blank" rel="noreferrer">Building effective agents</a></p><h2 id="共享验收要求" tabindex="-1">共享验收要求 <a class="header-anchor" href="#共享验收要求" aria-label="Permalink to &quot;共享验收要求&quot;">​</a></h2><p>每个主题至少留下一张数据流图、一份固定样本协议、一个消融对照和一类失败解释。对应用系统同时报告任务成功、证据或动作正确性、端到端延迟与资源消耗；必要时回到<a href="/evaluation/quality-systems">质量与服务实验</a>统一口径。</p><p>只做CPU模拟时，结论限定为机制与程序行为；调用真实模型时，保存模型/接口版本和逐样本输出；租赁硬件时，追加实际硬件与费用。本站尚未记录这组主题的个人实验结果。</p><p>核验日期：2026-11-16。上述论文使用明确版本；Anthropic文章发布于2024-12-19，其页面已提示工具生态发生变化，这里仅引用其工作流与agent的架构区分，不把旧工具列表视作当前推荐栈。</p>',8)])])}const b=t(o,[["render",d]]);export{_ as __pageData,b as default};
